import { useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { useMutation } from "@tanstack/react-query";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { ACTIVITY_TYPE, activityTypeLabel } from "@/lib/crm/constants";
import { saveCrm, type CrmRow } from "@/lib/crm/crm.functions";
import { useOrganization } from "@/lib/org/org-context";
import { areas } from "./config";
import { asRowsFrom, useCrmQuery } from "./data";
import { CrmListPage, RecordDialog, renderCell } from "./list";
import { ResultState, Shell, StatusBadge, str } from "./shared";

const area = areas.atividades;

/**
 * Atividades.
 *
 * Concluir uma atividade é `crm_save('activity')` com `status=COMPLETED` e um
 * resultado — não um botão que "marca como lido". O reagendamento é a mesma
 * coisa: nova data e motivo. O servidor grava histórico antes e depois em
 * `crm_activity_history` e recusa alteração sem motivo, então a tela sempre pede
 * o motivo.
 */
export function ActivitiesPage() {
  const { currentOrganization, hasPermission } = useOrganization();
  const [editing, setEditing] = useState<CrmRow | null | undefined>(undefined);
  const [completing, setCompleting] = useState<CrmRow | null>(null);
  const [rescheduling, setRescheduling] = useState<CrmRow | null>(null);

  return (
    <>
      <CrmListPage
        area={area}
        title="Comercial · Atividades"
        intro="Tarefas, reuniões, ligações e visitas. Concluir ou reagendar exige resultado ou motivo, e cada mudança fica no histórico da atividade — nada é apagado."
        rowActions={(row) => {
          if (!hasPermission("activities.manage") || row.status !== "PENDING") return null;
          return (
            <>
              <Button size="sm" variant="outline" onClick={() => setCompleting(row)}>
                Concluir
              </Button>
              <Button size="sm" variant="outline" onClick={() => setRescheduling(row)}>
                Reagendar
              </Button>
            </>
          );
        }}
      />
      {currentOrganization ? (
        <>
          <ActivityDialogs
            org={currentOrganization.organization_id}
            completing={completing}
            rescheduling={rescheduling}
            onClose={() => {
              setCompleting(null);
              setRescheduling(null);
            }}
            onEdit={(row) => setEditing(row)}
          />
          {editing ? (
            <RecordDialog
              org={currentOrganization.organization_id}
              area={area}
              record={editing}
              onClose={() => setEditing(undefined)}
              onSaved={() => setEditing(undefined)}
            />
          ) : null}
        </>
      ) : null}
    </>
  );
}

function ActivityDialogs({
  org,
  completing,
  rescheduling,
  onClose,
  onEdit,
}: {
  org: string;
  completing: CrmRow | null;
  rescheduling: CrmRow | null;
  onClose: () => void;
  onEdit: (row: CrmRow) => void;
}) {
  const client = useQueryClient();
  const refresh = () => void client.invalidateQueries({ queryKey: ["crm"] });
  return (
    <>
      {completing ? (
        <CompleteDialog org={org} activity={completing} onClose={onClose} onDone={refresh} />
      ) : null}
      {rescheduling ? (
        <RescheduleDialog
          org={org}
          activity={rescheduling}
          onClose={onClose}
          onDone={() => {
            refresh();
            onEdit(rescheduling);
          }}
        />
      ) : null}
    </>
  );
}

/** Conclusão: resultado obrigatório. Sem resultado, não há o que registrar. */
function CompleteDialog({
  org,
  activity,
  onClose,
  onDone,
}: {
  org: string;
  activity: CrmRow;
  onClose: () => void;
  onDone: () => void;
}) {
  const [outcome, setOutcome] = useState("");
  return (
    <StatusChangeDialog
      org={org}
      activity={activity}
      title="Concluir atividade"
      description="O resultado fica registrado na atividade e no histórico. Concluir não gera pedido, não fatura e não altera a oportunidade."
      confirmLabel="Concluir"
      values={{ status: "COMPLETED", outcome, reason: outcome }}
      disabled={!outcome.trim()}
      onClose={onClose}
      onDone={onDone}
    />
  );
}

/** Reagendamento: nova data e motivo. O histórico guarda a data anterior. */
function RescheduleDialog({
  org,
  activity,
  onClose,
  onDone,
}: {
  org: string;
  activity: CrmRow;
  onClose: () => void;
  onDone: () => void;
}) {
  const [scheduledAt, setScheduledAt] = useState("");
  const [reason, setReason] = useState("");
  return (
    <StatusChangeDialog
      org={org}
      activity={activity}
      title="Reagendar atividade"
      description="A data anterior permanece no histórico da atividade. O servidor recusa reagendar sem motivo."
      confirmLabel="Reagendar"
      values={{ scheduled_at: scheduledAt, reason }}
      disabled={!scheduledAt || !reason.trim()}
      extra={
        <div className="space-y-1">
          <label className="text-sm" htmlFor="reschedule-at">
            Nova data e hora
          </label>
          <input
            id="reschedule-at"
            type="datetime-local"
            className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
            value={scheduledAt}
            onChange={(event) => setScheduledAt(event.target.value)}
          />
        </div>
      }
      onClose={onClose}
      onDone={onDone}
    />
  );
}

function StatusChangeDialog({
  org,
  activity,
  title,
  description,
  confirmLabel,
  values,
  disabled,
  extra,
  onClose,
  onDone,
}: {
  org: string;
  activity: CrmRow;
  title: string;
  description: string;
  confirmLabel: string;
  values: Record<string, string>;
  disabled?: boolean;
  extra?: React.ReactNode;
  onClose: () => void;
  onDone: () => void;
}) {
  const api = saveCrm.useServerFn?.() ?? null;
  void api;
  return (
    <StatusChangeForm
      org={org}
      activity={activity}
      title={title}
      description={description}
      confirmLabel={confirmLabel}
      values={values}
      disabled={disabled}
      extra={extra}
      onClose={onClose}
      onDone={onDone}
    />
  );
}

function StatusChangeForm({
  org,
  activity,
  title,
  description,
  confirmLabel,
  values,
  disabled,
  extra,
  onClose,
  onDone,
}: {
  org: string;
  activity: CrmRow;
  title: string;
  description: string;
  confirmLabel: string;
  values: Record<string, string>;
  disabled?: boolean;
  extra?: React.ReactNode;
  onClose: () => void;
  onDone: () => void;
}) {
  return (
    <ActivityMutationDialog
      org={org}
      activity={activity}
      title={title}
      description={description}
      confirmLabel={confirmLabel}
      values={values}
      disabled={disabled}
      extra={extra}
      onClose={onClose}
      onDone={onDone}
    />
  );
}

function ActivityMutationDialog({
  org,
  activity,
  title,
  description,
  confirmLabel,
  values,
  disabled,
  extra,
  onClose,
  onDone,
}: {
  org: string;
  activity: CrmRow;
  title: string;
  description: string;
  confirmLabel: string;
  values: Record<string, string>;
  disabled?: boolean;
  extra?: React.ReactNode;
  onClose: () => void;
  onDone: () => void;
}) {
  return (
    <DialogShell
      title={title}
      description={description}
      confirmLabel={confirmLabel}
      confirmDisabled={disabled}
      onClose={onClose}
      onConfirm={() => undefined}
      extra={extra}
    />
  );
}

function DialogShell({
  title,
  description,
  confirmLabel,
  confirmDisabled,
  onClose,
  onConfirm,
  extra,
}: {
  title: string;
  description: string;
  confirmLabel: string;
  confirmDisabled?: boolean;
  onClose: () => void;
  onConfirm: () => void;
  extra?: React.ReactNode;
}) {
  void onConfirm;
  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent className="sm:max-w-xl">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>
        {extra}
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancelar
          </Button>
          <Button disabled={confirmDisabled}>Confirmar</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Agenda da minha carteira: só as atividades do usuário ativo e da empresa visível.
 * A lista é ordenada por agendamento, e o passado aparece separado do futuro —
 * uma caixa de entrada com tudo junto esconde o que já venceu.
 */
export function MySchedulePage() {
  const { currentOrganization, hasPermission } = useOrganization();
  return (
    <Shell title="Comercial · Minha agenda" permission={area.permission}>
      {(org) => <MySchedule org={org} canWrite={hasPermission("activities.manage")} />}
    </Shell>
  );
}

function MySchedule({ org, canWrite }: { org: string; canWrite: boolean }) {
  const me = useOrganization().currentOrganization;
  void me;
  const query = useCrmQuery(org, "activities", { status: "PENDING" }, 1);
  const rows = asRowsFrom(query.data);
  const today = new Date().toISOString().slice(0, 10);
  const overdue = rows.filter((row) => String(row.scheduled_at ?? "").slice(0, 10) < today);
  const upcoming = rows.filter((row) => String(row.scheduled_at ?? "").slice(0, 10) >= today);

  return (
    <div className="space-y-5">
      <h2 className="font-heading text-xl font-semibold">Minha agenda</h2>
      <ResultState loading={query.isLoading} error={query.error} empty={!rows.length}>
        <div className="grid gap-4 lg:grid-cols-2">
          <ActivityGroup
            title="Atrasadas"
            rows={overdue}
            canWrite={canWrite}
            empty="Nada atrasado."
          />
          <ActivityGroup
            title="Próximas"
            rows={upcoming}
            canWrite={canWrite}
            empty="Nada agendado."
          />
        </div>
        <p className="text-sm text-muted-foreground">
          {rows.length} atividades pendentes no total. A lista vem da mesma consulta do servidor, que
          já aplica o escopo de carteira.
        </p>
      </ResultState>
    </div>
  );
}

function ActivityGroup({
  title,
  rows,
  canWrite,
  empty,
}: {
  title: string;
  rows: CrmRow[];
  canWrite: boolean;
  empty: string;
}) {
  return (
    <Card>
      <CardContent className="space-y-2 pt-6">
        <h3 className="font-heading text-base font-semibold">
          {title} <span className="text-sm font-normal text-muted-foreground">({rows.length})</span>
        </h3>
        <ul className="space-y-2">
          {rows.map((row) => (
            <li key={row.id} className="space-y-1 rounded-lg border p-3 text-sm">
              <div className="flex items-start justify-between gap-3">
                <span className="font-medium">{str(row.subject)}</span>
                <StatusBadge value={row.status} kind="status" />
              </div>
              <p className="text-muted-foreground">
                {activityTypeLabel(String(row.activity_type))} · {str(row.scheduled_at)}
              </p>
              {row.company_id ? (
                <p className="text-xs text-muted-foreground">Cliente vinculado</p>
              ) : null}
            </li>
          ))}
          {!rows.length ? <li className="text-sm text-muted-foreground">{empty}</li> : null}
        </ul>
        {canWrite ? null : (
          <p className="text-xs text-muted-foreground">Você pode consultar, não alterar.</p>
        )}
      </CardContent>
    </Card>
  );
}

export { renderCell, ACTIVITY_TYPE, useMutation, Textarea };

import { useState, type ReactNode } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useServerFn } from "@tanstack/react-start";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { activityTypeLabel } from "@/lib/crm/constants";
import { saveCrm, type CrmRow } from "@/lib/crm/crm.functions";
import { useOrganization } from "@/lib/org/org-context";
import { areas } from "./config";
import { asRowsFrom, useCrmQuery } from "./data";
import { CrmListPage } from "./list";
import { ResultState, Shell, StatusBadge, str } from "./shared";

const area = areas.atividades;

/**
 * Atividades.
 *
 * Concluir é `crm_save('activity')` com `status=COMPLETED` e resultado; reagendar
 * é a mesma gravação com nova data e motivo. O servidor guarda o antes e o depois
 * em `crm_activity_history` e recusa alteração sem motivo, então a tela sempre
 * pergunta o motivo em vez de presumir.
 */
export function ActivitiesPage() {
  return (
    <CrmListPage
      area={area}
      title="Comercial · Atividades"
      intro="Tarefas, reuniões, ligações e visitas. Concluir ou reagendar exige resultado ou motivo, e cada mudança fica no histórico da atividade — nada é apagado."
      rowActions={<ActivityRowActions />}
    />
  );
}

/** Ações por linha. Fica isolado para o `CrmListPage` continuar sem estado próprio. */
function ActivityRowActions() {
  return null;
}

/** Corpo da listagem, com os diálogos de conclusão e reagendamento. */
function ActivitiesBody() {
  return null;
}

/**
 * Alteração de status ou data de uma atividade. Um único formulário serve para
 * concluir e para reagendar: a diferença são os campos exigidos, não o fluxo.
 */
function ActivityDialog({
  org,
  activity,
  title,
  description,
  confirmLabel,
  fields,
  onClose,
  onDone,
}: {
  org: string;
  activity: CrmRow;
  title: string;
  description: string;
  confirmLabel: string;
  fields: { key: string; label: string; type: string; required: boolean }[];
  onClose: () => void;
  onDone: () => void;
}) {
  const api = useServerFn(saveCrm);
  const [values, setValues] = useState<Record<string, string>>({});

  const save = useMutation({
    mutationFn: async () => {
      const payload: Record<string, unknown> = { id: activity.id };
      for (const field of fields) {
        const raw = values[field.key];
        // Campo vazio é omitido: em patch, string vazia zeraria o valor gravado.
        if (raw !== undefined && raw !== "") payload[field.key] = raw;
      }
      await api({ data: { organizationId: org, kind: "activity", values: payload } });
    },
    onSuccess: () => {
      toast.success("Atividade atualizada.");
      onClose();
      onDone();
    },
    onError: (error: Error) => toast.error(error.message),
  });

  const ready = fields.every((field) => !field.required || Boolean(values[field.key]?.trim()));

  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent className="sm:max-w-xl">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          {fields.map((field) => (
            <div key={field.key} className="space-y-1">
              <label className="text-sm" htmlFor={`activity-${field.key}`}>
                {field.label}
              </label>
              <input
                id={`activity-${field.key}`}
                type={field.type}
                className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
                value={values[field.key] ?? ""}
                onChange={(event) => setValues({ ...values, [field.key]: event.target.value })}
              />
            </div>
          ))}
        </div>
        <p className="text-xs text-muted-foreground">
          Atividade: {str(activity.subject)} ({activityTypeLabel(String(activity.activity_type))}).
        </p>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancelar
          </Button>
          <Button disabled={save.isPending || !ready} onClick={() => save.mutate()}>
            {save.isPending ? "Salvando..." : confirmLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Agenda: o que já venceu fica separado do que ainda vai acontecer. Uma caixa de
 * entrada com tudo junto esconde o atraso, que é justamente o que a agenda serve
 * para mostrar. A lista vem da mesma consulta do servidor, que já aplica o escopo
 * de carteira — a tela não filtra por conta própria.
 */
export function MySchedulePage() {
  return (
    <Shell title="Comercial · Minha agenda" permission={area.permission}>
      {(org) => <MySchedule org={org} />}
    </Shell>
  );
}

function MySchedule({ org }: { org: string }) {
  const query = useCrmQuery(org, "activities", { status: "PENDING" }, 1);
  const rows = asRowsFrom(query.data);
  const today = new Date().toISOString().slice(0, 10);
  const overdue = rows.filter((row) => String(row.scheduled_at ?? "").slice(0, 10) < today);
  const upcoming = rows.filter((row) => String(row.scheduled_at ?? "").slice(0, 10) >= today);

  return (
    <div className="space-y-5">
      <h2 className="font-heading text-xl font-semibold">Minha agenda</h2>
      <ResultState loading={query.isLoading} error={query.error} empty={!rows.length}>
        <div className="grid gap-4 lg:grid-cols-2">
          <ActivityGroup title="Atrasadas" rows={overdue} empty="Nada atrasado." />
          <ActivityGroup title="Próximas" rows={upcoming} empty="Nada agendado." />
        </div>
        <p className="text-sm text-muted-foreground">
          {rows.length} atividades pendentes no total.
        </p>
      </ResultState>
    </div>
  );
}

function ActivityGroup({ title, rows, empty }: { title: string; rows: CrmRow[]; empty: string }) {
  return (
    <Card>
      <CardContent className="space-y-2 pt-6">
        <h3 className="font-heading text-base font-semibold">
          {title} <span className="text-sm font-normal text-muted-foreground">({rows.length})</span>
        </h3>
        <ul className="space-y-2">
          {rows.map((row) => (
            <li key={row.id} className="space-y-1 rounded-lg border p-3 text-sm">
              <div className="flex items-start justify-between gap-3">
                <span className="font-medium">{str(row.subject)}</span>
                <StatusBadge value={row.status} kind="status" />
              </div>
              <p className="text-muted-foreground">
                {activityTypeLabel(String(row.activity_type))} · {str(row.scheduled_at)}
              </p>
            </li>
          ))}
          {!rows.length ? <li className="text-sm text-muted-foreground">{empty}</li> : null}
        </ul>
      </CardContent>
    </Card>
  );
}

/**
 * Tela completa de atividades com os diálogos. `CrmListPage` já resolve
 * organização, permissão e paginação; aqui ficam apenas as duas transições que a
 * listagem declarativa não conhece.
 */
export function ActivitiesPageWithDialogs() {
  const { currentOrganization, hasPermission } = useOrganization();
  const client = useQueryClient();
  const [target, setTarget] = useState<{ row: CrmRow; mode: "complete" | "reschedule" } | null>(null);

  if (!currentOrganization) return <CrmListPage area={area} title="Comercial · Atividades" />;
  const org = currentOrganization.organization_id;
  const canManage = hasPermission("activities.manage");

  return (
    <>
      <CrmListPage
        area={area}
        title="Comercial · Atividades"
        intro="Tarefas, reuniões, ligações e visitas. Concluir ou reagendar exige resultado ou motivo, e cada mudança fica no histórico da atividade."
        rowActions={(row) => {
          if (!canManage || row.status !== "PENDING") return null;
          return (
            <>
              <Button size="sm" variant="outline" onClick={() => setTarget({ row, mode: "complete" })}>
                Concluir
              </Button>
              <Button size="sm" variant="outline" onClick={() => setTarget({ row, mode: "reschedule" })}>
                Reagendar
              </Button>
            </>
          );
        }}
      />
      {target?.mode === "complete" ? (
        <ActivityDialog
          org={org}
          activity={target.row}
          title="Concluir atividade"
          description="O resultado fica na atividade e no histórico. Concluir não gera pedido, não fatura e não altera a oportunidade."
          confirmLabel="Concluir"
          fields={[
            { key: "status", label: "Novo status", type: "text", required: true },
            { key: "outcome", label: "Resultado", type: "text", required: true },
            { key: "reason", label: "Motivo", type: "text", required: true },
          ]}
          onClose={() => setTarget(null)}
          onDone={() => void client.invalidateQueries({ queryKey: ["crm"] })}
        />
      ) : null}
      {target?.mode === "reschedule" ? (
        <ActivityDialog
          org={org}
          activity={target.row}
          title="Reagendar atividade"
          description="A data anterior permanece no histórico. O servidor recusa reagendar sem motivo."
          confirmLabel="Reagendar"
          fields={[
            { key: "scheduled_at", label: "Nova data e hora", type: "datetime-local", required: true },
            { key: "reason", label: "Motivo", type: "text", required: true },
          ]}
          onClose={() => setTarget(null)}
          onDone={() => void client.invalidateQueries({ queryKey: ["crm"] })}
        />
      ) : null}
    </>
  );
}

export type { ReactNode };

import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useServerFn } from "@tanstack/react-start";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { activityTypeLabel } from "@/lib/crm/constants";
import { saveCrm, type CrmRow } from "@/lib/crm/crm.functions";
import { useOrganization } from "@/lib/org/org-context";
import { areas } from "./config";
import { asRowsFrom, useCrmQuery } from "./data";
import { CrmListPage } from "./list";
import { ResultState, Shell, StatusBadge, str } from "./shared";

const area = areas.atividades;

/**
 * Atividades.
 *
 * Concluir é `crm_save('activity')` com `status=COMPLETED` e resultado;
 * reagendar é a mesma gravação com nova data e motivo. O status não é digitado
 * pelo usuário — a tela oferece só as duas transições que o servidor aceita, e
 * ambas exigem justificativa, porque o histórico é gravado antes e depois.
 */
export function ActivitiesPage() {
  const { currentOrganization, hasPermission } = useOrganization();
  const client = useQueryClient();
  const [target, setTarget] = useState<{ row: CrmRow; mode: "complete" | "reschedule" } | null>(
    null,
  );

  const org = currentOrganization?.organization_id ?? "";
  const canManage = hasPermission("activities.manage");
  const refresh = () => void client.invalidateQueries({ queryKey: ["crm"] });

  return (
    <>
      <CrmListPage
        area={area}
        title="Comercial · Atividades"
        intro="Tarefas, reuniões, ligações e visitas. Concluir ou reagendar exige resultado ou motivo, e cada mudança fica no histórico da atividade — nada é apagado."
        rowActions={(row) => {
          if (!canManage || row.status !== "PENDING") return null;
          return (
            <>
              <Button size="sm" variant="outline" onClick={() => setTarget({ row, mode: "complete" })}>
                Concluir
              </Button>
              <Button size="sm" variant="outline" onClick={() => setTarget({ row, mode: "reschedule" })}>
                Reagendar
              </Button>
            </>
          );
        }}
      />

      {target?.mode === "complete" ? (
        <ActivityDialog
          org={org}
          activity={target.row}
          title="Concluir atividade"
          description="O resultado fica na atividade e no histórico. Concluir não gera pedido, não fatura e não altera a oportunidade."
          confirmLabel="Concluir"
          fixed={{ status: "COMPLETED" }}
          fields={[
            { key: "outcome", label: "Resultado", type: "text", required: true },
            { key: "reason", label: "Motivo do registro", type: "text", required: true },
          ]}
          onClose={() => setTarget(null)}
          onDone={refresh}
        />
      ) : null}

      {target?.mode === "reschedule" ? (
        <ActivityDialog
          org={org}
          activity={target.row}
          title="Reagendar atividade"
          description="A data anterior permanece no histórico da atividade. O servidor recusa reagendar sem motivo."
          confirmLabel="Reagendar"
          fields={[
            { key: "scheduled_at", label: "Nova data e hora", type: "datetime-local", required: true },
            { key: "reason", label: "Motivo", type: "text", required: true },
          ]}
          onClose={() => setTarget(null)}
          onDone={refresh}
        />
      ) : null}
    </>
  );
}

type ActivityField = { key: string; label: string; type: string; required: boolean };

/**
 * Alteração de uma atividade existente. Um único formulário serve para concluir e
 * para reagendar: mudam os campos exigidos, não o fluxo. `fixed` carrega valores
 * que a tela decide (o novo status) e que não fazem sentido como entrada de texto.
 */
function ActivityDialog({
  org,
  activity,
  title,
  description,
  confirmLabel,
  fields,
  fixed,
  onClose,
  onDone,
}: {
  org: string;
  activity: CrmRow;
  title: string;
  description: string;
  confirmLabel: string;
  fields: ActivityField[];
  fixed?: Record<string, string>;
  onClose: () => void;
  onDone: () => void;
}) {
  const api = useServerFn(saveCrm);
  const [values, setValues] = useState<Record<string, string>>({});

  const save = useMutation({
    mutationFn: async () => {
      const payload: Record<string, unknown> = { id: activity.id, ...(fixed ?? {}) };
      for (const field of fields) {
        const raw = values[field.key];
        // Campo vazio é omitido: em patch, string vazia zeraria o valor gravado.
        if (raw !== undefined && raw !== "") payload[field.key] = raw;
      }
      await api({ data: { organizationId: org, kind: "activity", values: payload } });
    },
    onSuccess: () => {
      toast.success("Atividade atualizada.");
      onClose();
      onDone();
    },
    onError: (error: Error) => toast.error(error.message),
  });

  const ready = fields.every((field) => !field.required || Boolean(values[field.key]?.trim()));

  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent className="sm:max-w-xl">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          {fields.map((field) => (
            <div key={field.key} className="space-y-1">
              <label className="text-sm" htmlFor={`activity-${field.key}`}>
                {field.label}
              </label>
              <input
                id={`activity-${field.key}`}
                type={field.type}
                className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
                value={values[field.key] ?? ""}
                onChange={(event) => setValues({ ...values, [field.key]: event.target.value })}
              />
            </div>
          ))}
        </div>
        <p className="text-xs text-muted-foreground">
          {str(activity.subject)} · {activityTypeLabel(String(activity.activity_type))} · agendada
          para {str(activity.scheduled_at)}
        </p>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancelar
          </Button>
          <Button disabled={save.isPending || !ready} onClick={() => save.mutate()}>
            {save.isPending ? "Salvando..." : confirmLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Agenda: o que já venceu fica separado do que ainda vai acontecer. Uma caixa de
 * entrada com tudo junto esconde o atraso, que é justamente o que a agenda existe
 * para mostrar. A lista vem da mesma consulta do servidor, que já aplica o escopo
 * de carteira — a tela não filtra por conta própria.
 */
export function MySchedulePage() {
  return (
    <Shell title="Comercial · Minha agenda" permission={area.permission}>
      {(org) => <MySchedule org={org} />}
    </Shell>
  );
}

function MySchedule({ org }: { org: string }) {
  const query = useCrmQuery(org, "activities", { status: "PENDING" }, 1);
  const rows = asRowsFrom(query.data);
  const today = new Date().toISOString().slice(0, 10);
  const overdue = rows.filter((row) => String(row.scheduled_at ?? "").slice(0, 10) < today);
  const upcoming = rows.filter((row) => String(row.scheduled_at ?? "").slice(0, 10) >= today);

  return (
    <div className="space-y-5">
      <h2 className="font-heading text-xl font-semibold">Minha agenda</h2>
      <ResultState loading={query.isLoading} error={query.error} empty={!rows.length}>
        <div className="grid gap-4 lg:grid-cols-2">
          <ActivityGroup title="Atrasadas" rows={overdue} empty="Nada atrasado." />
          <ActivityGroup title="Próximas" rows={upcoming} empty="Nada agendado." />
        </div>
        <p className="text-sm text-muted-foreground">{rows.length} atividades pendentes no total.</p>
      </ResultState>
    </div>
  );
}

function ActivityGroup({ title, rows, empty }: { title: string; rows: CrmRow[]; empty: string }) {
  return (
    <Card>
      <CardContent className="space-y-2 pt-6">
        <h3 className="font-heading text-base font-semibold">
          {title} <span className="text-sm font-normal text-muted-foreground">({rows.length})</span>
        </h3>
        <ul className="space-y-2">
          {rows.map((row) => (
            <li key={row.id} className="space-y-1 rounded-lg border p-3 text-sm">
              <div className="flex items-start justify-between gap-3">
                <span className="font-medium">{str(row.subject)}</span>
                <StatusBadge value={row.status} kind="status" />
              </div>
              <p className="text-muted-foreground">
                {activityTypeLabel(String(row.activity_type))} · {str(row.scheduled_at)}
              </p>
            </li>
          ))}
          {!rows.length ? <li className="text-sm text-muted-foreground">{empty}</li> : null}
        </ul>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useServerFn } from "@tanstack/react-start";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { actCrm, type CrmRow } from "@/lib/crm/crm.functions";
import { useOrganization } from "@/lib/org/org-context";
import { areas } from "./config";
import { asRowsFrom, useCrmQuery } from "./data";
import { CrmListPage, renderCell } from "./list";
import { Picker, ResultState, StatusBadge, str } from "./shared";

/**
 * Representantes.
 *
 * A lista é declarativa. A diferença real está na carteira: representante
 * interno, externo ou da própria empresa muda o que a operação pode esperar dele,
 * e isso é atributo do cadastro, não uma coluna calculada na tela.
 */
export function RepresentativesPage() {
  return (
    <CrmListPage
      area={areas.representantes}
      title="Comercial · Representantes"
      intro="Quem negocia pela organização. Um representante pode ser interno, externo ou a própria empresa comercial, e o tipo é gravado no cadastro porque muda a regra de carteira."
    />
  );
}

const portfolioArea = areas.carteiras;

/**
 * Carteiras.
 *
 * A atribuição é `crm_action('portfolio','assign')` e não um INSERT: encerrar a
 * carteira anterior e abrir a nova acontece na mesma transação, com motivo
 * obrigatório, e o histórico permanece. Por isso esta tela não usa o formulário
 * declarativo — a escrita de carteira não é um `crm_save`.
 */
export function PortfoliosPage() {
  return (
    <CrmListPage
      area={portfolioArea}
      title="Comercial · Carteiras"
      intro="Cada cliente tem uma carteira ativa. A transferência encerra a anterior, abre a nova com motivo e não reescreve o responsável de negociações já existentes."
    />
  );
}

/** Atribuição de carteira, com a lista de clientes do representante. */
export function AssignPortfolioButton() {
  const { currentOrganization, hasPermission } = useOrganization();
  const [open, setOpen] = useState(false);
  if (!hasPermission("portfolios.manage")) return null;
  return (
    <>
      <Button onClick={() => setOpen(true)}>Atribuir carteira</Button>
      {open && currentOrganization ? (
        <AssignDialog
          org={currentOrganization.organization_id}
          onClose={() => setOpen(false)}
        />
      ) : null}
    </>
  );
}

function AssignDialog({ org, onClose }: { org: string; onClose: () => void }) {
  const api = useServerFn(actCrm);
  const client = useQueryClient();
  const [companyId, setCompanyId] = useState("");
  const [representativeId, setRepresentativeId] = useState("");
  const [reason, setReason] = useState("");
  const [key, setKey] = useState(() => crypto.randomUUID());

  const assign = useMutation({
    mutationFn: async () => {
      await api({
        data: {
          organizationId: org,
          kind: "portfolio",
          id: companyId,
          action: "assign",
          values: { representative_id: representativeId, reason },
          key,
        },
      });
    },
    onSuccess: () => {
      toast.success("Carteira atribuída.");
      onClose();
      void client.invalidateQueries({ queryKey: ["crm"] });
    },
    onError: (error: Error) => {
      setKey(crypto.randomUUID());
      toast.error(error.message);
    },
  });

  return (
    <Dialog
      open
      onOpenChange={(next) => {
        if (!next) onClose();
      }}
    >
      <DialogContent className="sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>Atribuir carteira</DialogTitle>
          <DialogDescription>
            A carteira ativa anterior é encerrada na mesma transação e permanece no histórico. O
            motivo é obrigatório, e apenas representantes ativos aceitam carteira.
          </DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 sm:grid-cols-2">
          <Picker org={org} kind="companies" value={companyId} onChange={setCompanyId} label="Cliente" />
          <Picker
            org={org}
            kind="representatives"
            value={representativeId}
            onChange={setRepresentativeId}
            label="Representante"
          />
          <div className="space-y-1 sm:col-span-2">
            <label className="text-sm" htmlFor="portfolio-reason">
              Motivo
            </label>
            <input
              id="portfolio-reason"
              className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
              value={reason}
              onChange={(event) => setReason(event.target.value)}
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancelar
          </Button>
          <Button
            disabled={assign.isPending || !companyId || !representativeId || !reason.trim()}
            onClick={() => assign.mutate()}
          >
            {assign.isPending ? "Atribuindo..." : "Atribuir"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Carteira de um representante: clientes ativos e histórico de transferências.
 * O histórico vem da mesma tabela de atribuições, filtrada por representante — não
 * de uma coluna denormalizada que o servidor teria de manter.
 */
export function RepresentativePortfolioPage({ id }: { id: string }) {
  const { currentOrganization, hasPermission } = useOrganization();
  const rows = useCrmQuery(currentOrganization?.organization_id ?? "", "portfolios", {}, 1);
  const companies = useCrmQuery(currentOrganization?.organization_id ?? "", "companies", {}, 1);
  const assignments = asRowsFrom(rows.data).filter(
    (row) => String(row.representative_id) === id,
  );
  const name = (row: CrmRow) => str(row.name ?? row.legal_name ?? row.id);
  const companyName = new Map(
    asRowsFrom(companies.data).map((row) => [row.id, name(row)]),
  );

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h2 className="font-heading text-xl font-semibold">Carteira do representante</h2>
        {hasPermission("portfolios.manage") ? <AssignPortfolioButton /> : null}
      </div>

      <ResultState loading={rows.isLoading} error={rows.error} empty={!assignments.length}>
        <div className="grid gap-4 lg:grid-cols-2">
          <Card>
            <CardContent className="space-y-2 pt-6">
              <h3 className="font-heading text-base font-semibold">Clientes ativos</h3>
              <ul className="space-y-1 text-sm">
                {assignments
                  .filter((row) => !row.ended_at)
                  .map((row) => (
                    <li key={row.id} className="flex items-center justify-between gap-3 border-b py-1">
                      <a
                        href={`/comercial/clientes/${String(row.company_id)}`}
                        className="hover:underline"
                      >
                        {companyName.get(String(row.company_id)) ?? str(row.company_id)}
                      </a>
                      <span className="text-xs text-muted-foreground">
                        desde {str(row.started_at)}
                      </span>
                    </li>
                  ))}
                {!assignments.filter((row) => !row.ended_at).length ? (
                  <li className="text-muted-foreground">Nenhum cliente ativo.</li>
                ) : null}
              </ul>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="space-y-2 pt-6">
              <h3 className="font-heading text-base font-semibold">Histórico</h3>
              <ul className="space-y-1 text-sm">
                {assignments.map((row) => (
                  <li key={row.id} className="space-y-0.5 border-b py-1">
                    <div className="flex items-center justify-between gap-3">
                      <span>{companyName.get(String(row.company_id)) ?? str(row.company_id)}</span>
                      {row.ended_at ? (
                        <StatusBadge value="HISTORICO" kind="status" />
                      ) : (
                        <StatusBadge value="ACTIVE" kind="status" />
                      )}
                    </div>
                    <p className="text-xs text-muted-foreground">
                      {str(row.started_at)}
                      {row.ended_at ? ` → ${str(row.ended_at)}` : ""}
                      {row.reason ? ` · ${str(row.reason)}` : ""}
                    </p>
                  </li>
                ))}
              </ul>
            </CardContent>
          </Card>
        </div>
      </ResultState>

      <p className="text-xs text-muted-foreground">
        A negociação já registrada mantém o representante que estava na carteira quando foi criada.
        O移 responsável reflete o estado atual da carteira, não o passado da negociação.
      </p>
    </div>
  );
}

export { renderCell };

